        getPerformanceSummary(history) {
            if (!history.length) return {};
            var revenues = history.map(function(r) { return r.results ? r.results.revenue || 0 : 0; });
            var totalRevenue = revenues.reduce(function(s, v) { return s + v; }, 0);
            var avgRevenue = totalRevenue / revenues.length;
            var finalSentiment = history[history.length - 1].results ? history[history.length - 1].results.sentiment || 0 : 0;
            var finalFollowers = history[history.length - 1].results ? history[history.length - 1].results.totalFollowers || 0 : 0;

            var t = this._t.bind(this);
            var performance = t('tier_beginner');
            if (totalRevenue > 2500000 && finalSentiment > 60) performance = t('tier_competent');
            if (totalRevenue > 4000000 && finalSentiment > 70) performance = t('tier_expert');
            if (totalRevenue > 5500000 && finalSentiment > 80) performance = t('tier_strategist');

            var insights = [];
            if (finalSentiment < 50) insights.push(t('insight_low_sentiment'));
            if (finalSentiment >= 70) insights.push(t('insight_good_sentiment'));
            if (totalRevenue > 4000000) insights.push(t('insight_good_revenue'));
            if (finalFollowers > 300000) insights.push(t('insight_great_growth'));
            if (insights.length === 0) insights.push(t('insight_default'));

            return {
                totalRevenue: totalRevenue,
                avgRevenue: avgRevenue,
                finalSentiment: finalSentiment,
                finalFollowers: finalFollowers,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.sentiment < 40) return window.mySimulation.t('hint_low_sentiment');
            if (results.engagementRate < 2.0) return window.mySimulation.t('hint_low_engagement');
            if (results.revenue < 5000000) return window.mySimulation.t('hint_low_revenue');
            if (results.sentiment > 75 && results.revenue > 15000000) return window.mySimulation.t('hint_great');
            return null;
