        _renderDebrief(state) {
            var ds = state.domainState;
            if (!ds) return;
            var t = this._t.bind(this);
            var totalRevenue = ds.totalRevenue, finalSentiment = ds.brandSentiment, finalFollowers = ds.totalFollowers;
            var performance = t('tier_beginner');
            if (totalRevenue > 2500000 && finalSentiment > 60) performance = t('tier_competent');
            if (totalRevenue > 4000000 && finalSentiment > 70) performance = t('tier_expert');
            if (totalRevenue > 5500000 && finalSentiment > 80) performance = t('tier_strategist');
            var insights = [];
            if (finalSentiment < 50) insights.push(t('insight_low_sentiment'));
            if (finalSentiment >= 70) insights.push(t('insight_good_sentiment'));
            if (totalRevenue > 4000000) insights.push(t('insight_good_revenue'));
            if (finalFollowers > 300000) insights.push(t('insight_great_growth'));
            if (insights.length === 0) insights.push(t('insight_default'));
            var panel = document.getElementById('debriefPanel');
            if (!panel) return;
            var fmt = function(v) { return Math.round(v).toLocaleString(); };
            var tierEl = document.getElementById('debriefTier');
            var metricsEl = document.getElementById('debriefMetrics');
            var insightsEl = document.getElementById('debriefInsights');
            if (tierEl) tierEl.innerHTML = t('debrief_tier_label') + ': <strong>' + performance + '</strong>';
            if (metricsEl) metricsEl.innerHTML =
                '<span>' + t('revenue_label') + ': $' + fmt(totalRevenue) + '</span>' +
                '<span>' + t('sentiment_label') + ': ' + finalSentiment + '%</span>' +
                '<span>' + t('followers_label') + ': ' + fmt(finalFollowers) + '</span>';
            if (insightsEl) insightsEl.innerHTML = insights.map(function(x) { return '<li>' + x + '</li>'; }).join('');
            panel.style.display = 'block';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._t(round.briefingKey);

            var crisisPanel = document.getElementById('crisisPanel');
            var crisisDesc = document.getElementById('crisisDescription');
            if (crisisPanel) crisisPanel.style.display = round.hasCrisis ? 'block' : 'none';
            if (crisisDesc) crisisDesc.innerHTML = round.crisisKey ? this._t(round.crisisKey) : '';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new SocialMediaAdapter(), {
            simulationType: 'social_media_marketing_620',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
